1	// baselining worker — the DETERMINISTIC self-refresh, as prework
2	// (task-prework DESIGN §7, E4). This is `agent_model: 'sonnet'` with
3	// `prework: 'node worker.mjs'`, so the scheduler runs THIS FILE as a
4	// subprocess (cwd = this task dir) bounded by `prework_timeout`,
5	// BEFORE any agent. It absorbs everything about the nightly refresh that is
6	// dependency-free code — so most nights are AGENTLESS and quiet, and an agent is
7	// requested only when real judgment is left (owner decision, 2026-07-23):
8	//
9	//   agent requested  ⇔  a pending AGENTIC migration note exists
10	//                    OR  the converge changed things AND check_the_world is not green.
11	//   no change, or changed-but-green with no agentic note  →  agentless night.
12	//
13	// What it does, Action-side, over the one sanctioned non-MCP surface (the Action
14	// GITHUB_TOKEN in env) and a direct PUBLIC canon fetch (owner §10: canon is
15	// public — no token, no tarball channel):
16	//   1. shallow-clone canon at its head sha (then drop .git → a rootless tree, so
17	//      apply-vendor-set skips the ancestry guards that a shallow clone can't
18	//      satisfy — it is head by construction);
19	//   2. run the CLONED canon's vendoring/apply-vendor-set.mjs to converge
20	//      .claudinite/shared/ and stamp it (compute+apply, one snapshot);
21	//   3. run the cloned converge-wiring.mjs (scheduler workflow + hashed cron + the
22	//      tasks' declared required_secrets, settings hooks, retired-import removal),
23	//      and ask the owner for any declared secret the repo hasn't configured;
24	//   4. apply the MECHANICAL migration notes (aliases/materialize/rewrite/declarePacks)
25	//      via the cloned migrations/apply.mjs — idempotent — and re-converge the mount
26	//      when that changed the DECLARATION, since a newly declared pack's content was
27	//      not in the set the vendor pass computed a moment earlier;
28	//   5. detect pending AGENTIC notes (registry.mjs `agenticMigrations`, gated on
29	//      the prior stamp day, same-day inclusive #330) and, if any, HOLD the stamp
30	//      at the day before the earliest one so the agent still sees the note (the
31	//      stamp/agentic coupling rule);
32	//   6. deliver the converge as ONE commit on the per-cycle maintenance branch via
33	//      NATIVE git (dispose of the family's open PR — merge it if its own runs
34	//      verified it, else close it — then cut a fresh dated branch and open the
35	//      PR), arming auto-merge per the
36	//      member's `maintenance.delivery` and DISPATCHING the repo's PR CI on the
37	//      branch — the GITHUB_TOKEN push emits no pull_request run of its own
38	//      (#565), so the checks the arm waits on must be started explicitly;
39	//   7. request the agent (write CLAUDINITE_REQUEST_AGENT) only when judgment is
40	//      left — the scheduler files `ready-for-agent` iff this file appears (§3,
41	//      conditional handoff). NO code→agent data channel: the file is a pure
42	//      control signal; the agent discovers its work by reading the repo (the
43	//      pushed branch, the held stamp, the pending note).
44	//
45	// Imports: node builtins, plus the vendored ENGINE SURFACE — the one import the
46	// pack-independence barrier sanctions. The delivery/landing nuances live in
47	// `engine/scheduler/land-pr.mjs` (one home for every PR-delivering task; its
48	// helpers grew here and moved out), vendored beside this worker and loaded at
49	// process start — so the mid-run mount overwrite (apply-vendor-set rewriting the
50	// tree this process is executing from) can never mix an old worker with new
51	// landing logic. The vendoring/migrations machinery stays canon-internal
52	// (vendoring/ is never vendored, #385), so the worker INVOKES the
53	// freshly-fetched canon's scripts as subprocesses and DYNAMIC-imports its
54	// registry from the temp clone path — never a static import of that code.
55	//
56	// This SUPERSEDES the per-cycle maintenance-branch naming of PR #407 (that PR
57	// reworked the OLD fleet-apply MCP path; baselining's delivery is native git
58	// Action-side and carries its own prefix/find-by-prefix here).
59	
60	import { execFileSync } from 'node:child_process';
61	import { readFileSync, writeFileSync, existsSync, rmSync, mkdtempSync } from 'node:fs';
62	import { join } from 'node:path';
63	import { tmpdir } from 'node:os';
64	import { pathToFileURL } from 'node:url';
65	// The shared landing helpers (see the header note): delivery resolution, the
66	// PR-open status check, and the whole arm/land/merge decision live there — this
67	// worker keeps only what is baselining-shaped (the family branch and its
68	// close-and-recut disposal).
69	import {
70	  resolveDelivery, pullCreateError, landDelivery,
71	  pullDisposition, mergeReason, failureSummary, deleteBranch,
72	} from '../../../../engine/scheduler/land-pr.mjs';
73	
74	const CANON_URL = 'https://github.com/missingbulb/Claudinite.git'; // public — no token
75	const MAINT_PREFIX = 'claudinite/maintenance';
76	const API = 'https://api.github.com';
77	
78	// --- pure helpers (exported, unit-tested git-free) --------------------------
79	
80	// The pending AGENTIC notes: those dated on/after the DAY of the prior stamp
81	// (same-day inclusive, #330), oldest first. `agenticList` is registry.mjs
82	// `agenticMigrations(all)` — already filtered to records carrying a valid
83	// `agentic` note (a malformed note throws THERE, aborting the run loudly).
84	export function pendingAgentic(agenticList, priorUpdated) {
85	  const priorDay = String(priorUpdated ?? '').slice(0, 10);
86	  return [...(agenticList ?? [])]
87	    .filter((m) => !priorDay || String(m.landed) >= priorDay)
88	    .sort((a, b) => String(a.landed).localeCompare(String(b.landed)));
89	}
90	
91	// HOLD the stamp at the day before the earliest pending agentic note (the
92	// stamp/agentic coupling rule): the note stays selected next run until the agent
93	// lands it and advances the stamp itself. Returns the held ISO datetime, or null
94	// when nothing is pending (the stamp advances normally).
95	export function heldStamp(pending) {
96	  if (!pending?.length) return null;
97	  const d = new Date(`${String(pending[0].landed).slice(0, 10)}T00:00:00.000Z`);
98	  d.setUTCDate(d.getUTCDate() - 1);
99	  return d.toISOString();
100	}
101	
102	// A per-cycle maintenance branch name — dated + a short seed so each cycle gets a
103	// distinct branch (superseding #407's scheme, native-git side). `seed` is passed
104	// in so this is pure; main() generates it.
105	export function maintenanceBranchName(dateStr, seed) {
106	  return `${MAINT_PREFIX}-${dateStr}-${seed}`;
107	}
108	
109	// The family's open maintenance PR, found by head-branch PREFIX (the name carries
110	// a per-cycle seed, so the prefix is what identifies the family): the cycle
111	// DISPOSES of this one — merge or close — before cutting its own, which is what
112	// keeps them from piling up night-over-night. null → nothing to dispose of. The
113	// whole PR is returned, not just its ref, because disposal needs its number and
114	// head sha.
115	export function openMaintenancePull(pulls, prefix = MAINT_PREFIX) {
116	  return (pulls ?? []).find((pr) => String(pr?.head?.ref ?? '').startsWith(prefix)) ?? null;
117	}
118	
119	// Its head branch alone — the shape most callers want.
120	export function openMaintenanceBranch(pulls, prefix = MAINT_PREFIX) {
121	  return openMaintenancePull(pulls, prefix)?.head?.ref ?? null;
122	}
123	
124	// The paths this stage is STRUCTURALLY UNABLE to deliver. deliver() pushes with the
125	// Action's GITHUB_TOKEN, and GitHub refuses to let that token create or update anything
126	// under `.github/workflows/` — there is no `permissions:` key that grants it. The refusal
127	// is remote-side and rejects the WHOLE ref, so a workflow file left in the commit fails
128	// the entire push, taking the mount convergence, the wiring and every other note with it.
129	//
130	// So the converge withholds exactly these paths and hands them to the AGENT stage, whose
131	// writes go through the session's MCP GitHub tools — a credential that does hold the
132	// `workflows` permission. The agent re-runs the same mechanical apply in its own checkout
133	// to produce them.
134	//
135	// It covers `convergeWiring`'s scheduler workflow as much as any pack-owned one.
136	export const UNPUSHABLE_PREFIX = '.github/workflows/';
137	export function withheldWorkflowPaths(changedPaths) {
138	  return (changedPaths ?? []).filter((p) => p.startsWith(UNPUSHABLE_PREFIX));
139	}
140	
141	// The escalation decision (owner, 2026-07-23): agent iff a pending agentic note,
142	// or a real change the deterministic converge left non-green. No change, or a
143	// green change with no agentic note, stays agentless.
144	//
145	// It returns the REASON, not a bit — `null` for an agentless night, otherwise
146	// `{ code, detail }`. The worker knew which of four conditions fired and then threw
147	// it away; the agent it woke re-derived all four from scratch, and on
148	// EdFringeAllocator#82 re-derived them WRONG (it reported "preprocessing created
149	// nothing" about a cycle that had merged its PR a second earlier) and closed a
150	// six-minute run as a no-op. `code` is the stable identifier a consumer branches on;
151	// `detail` is the sentence a human reads in the dispatch issue.
152	//
153	// It names the CONDITION and its counts, never the findings themselves — those stay
154	// in the repo for the agent to re-run (DESIGN §3, the no-code→agent-data-channel rule;
155	// the named exception is identity, not content).
156	//
157	// The branch ORDER is the escalation precedence, most-specific first: a night with a
158	// pending note and a red check is a note night, because the note is what the agent
159	// must apply and the red check may well be the note's own doing.
160	export function escalation({
161	  pendingCount, meaningfulChange, checksPass, selftestOk = true, withheldCount = 0,
162	  checksCrashed = false, selftestCrashed = false,
163	}) {
164	  if (pendingCount > 0) {
165	    return { code: 'agentic-notes', detail: `${pendingCount} pending agentic migration note(s) to apply` };
