404	  }
405	  const runs = (json?.workflow_runs ?? []).map((r) => ({ name: r.name, status: r.status, conclusion: r.conclusion }));
406	  const disposition = pullDisposition({ delivery, runs });
407	
408	  if (disposition === 'keep' || disposition === 'wait') {
